-- BeigePilot AI, Phase 2: knowledge, unanswered questions, handoff leads. Run ONE statement at a time in D1 Studio.
CREATE TABLE IF NOT EXISTS beigepilot_knowledge (id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL DEFAULT 'faq', title TEXT NOT NULL, answer TEXT NOT NULL, keywords TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'draft', created_at INTEGER NOT NULL DEFAULT (unixepoch()), updated_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS beigepilot_unanswered (id INTEGER PRIMARY KEY AUTOINCREMENT, question TEXT NOT NULL, qkey TEXT NOT NULL UNIQUE, times INTEGER NOT NULL DEFAULT 1, page TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'new', knowledge_id INTEGER, first_at INTEGER NOT NULL DEFAULT (unixepoch()), last_at INTEGER NOT NULL DEFAULT (unixepoch()));
CREATE TABLE IF NOT EXISTS beigepilot_leads (id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE, name TEXT NOT NULL, email TEXT NOT NULL, message TEXT NOT NULL, page TEXT NOT NULL DEFAULT '', consent INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'new', note TEXT NOT NULL DEFAULT '', owner_notify TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL DEFAULT (unixepoch()));
